update_blog.code:
const response = await client.blogs.updateBlog(1201, {blog: {
    title: 'Spring Sale Extended',
    content: '<p>The spring sale now runs one more week.</p>',
    date: '2026-09-28',
    is_published: true,
    visibility: 'restricted', visible_to: 'selected',
    categories: [{id: 31}],
    seo_configs: {meta_tag: [{name: 'description', value: 'Spring sale: up to 40% off'}]},
    selected_customers: {customers: [5501], groups: []},
